#!/bin/bash
# 4 варианта стиля UI — по очереди: codex_image забирает самый свежий PNG, параллельно перепутает
BASE="Mobile game UI concept, ONE vertical phone screenshot 9:16, for a kids' 3D party game 'КРУТИ ХАОС!' (Russian title, must be spelled exactly) where disasters fall on a floating grass island arena. Show the MAIN MENU over a blurred bright 3D arena background: big game logo 'КРУТИ ХАОС!' at top, three difficulty cards in a row labelled 'ЛЁГКИЙ', 'ОБЫЧНЫЙ', 'ХАОС' (middle one selected), a huge 'ИГРАТЬ' play button, below it two small buttons (characters icon, sound icon). In a small inset at the bottom-right corner, show the in-game HUD style: 3 hearts, a timer '0:45', a slot-machine reel panel with 3 reels and a round 'СТОП' button. All Russian text spelled exactly as given, no other text. Premium polished mobile game UI, readable for kids, high contrast. No existing brands or logos."
gen() { node tools/codex_image.cjs gen "art/ui/$1.png" "$BASE STYLE: $2" 2>&1 | grep -v Deprecation | tail -1; }
gen v1_candy "glossy candy cartoon like top casual mobile hits: chunky rounded buttons with thick dark outline, bright gradients, glossy highlights, bubbly 3D extruded logo letters, rounded heavy display font, playful bouncy feel."
gen v2_blocky "blocky toy-brick game style: panels and buttons look like chunky plastic building blocks with small studs and bevels, square-ish heavy pixel-free blocky font, saturated primary colors, cubic 3D logo made of blocks."
gen v3_comic "comic-book disaster pop style: thick black ink outlines, halftone dots, tilted sticker-like panels, yellow-black hazard stripes, explosion burst shapes behind the logo, bold condensed comic font with slight slant, energetic and chaotic but readable."
gen v4_neon "modern clean esports-casual style: dark translucent glass panels with rounded corners, vivid neon accents (orange, cyan, magenta), bold geometric wide font, logo with glowing outline, subtle motion streaks, sleek and minimal."
